@section('content')<section class="auth-page"><div class="auth-card"><div class="eyebrow">ACCOUNT SECURITY</div><h1>Reset password.</h1><form id="reset-form"><input type="hidden" name="token" value="{{ $token }}"><label>Email<input type="email" name="email" required></label><label>New password<input type="password" name="password" required minlength="8"></label><label>Confirm password<input type="password" name="password_confirmation" required minlength="8"></label><button class="button button-yellow button-wide">Reset password →</button><div id="reset-msg" class="form-message" hidden></div></form></div></section><script>document.getElementById('reset-form').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/reset-password',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const d=await r.json(),m=document.getElementById('reset-msg');m.hidden=false;m.className='form-message '+(r.ok?'success':'error');m.textContent=d.message||'Done.'})</script>@endsection
